    if (!user) return;

    setSubmitting(true);
    setMessage(null);

    try {
      if (editingBookmark) {
        // Update existing bookmark
        const { error } = await supabase
          .from("bookmarks")
          .update({
            title: data.title,
            url: data.url,
            is_public: data.is_public,
          })
          .eq("id", editingBookmark.id)
          .eq("user_id", user.id);

